# Viva — slot D2 (part A): dermatomyositis, SLE, systemic sclerosis, DLE
# Own words. Topics guided by the previous-year question book (Sahana P Raju) — CTD chapter (classify scleroderma,
# lupus band test, latest SLE classification, LE cell, calcinosis cutis, CREST, renal/cardiac SLE, Gottron's,
# tin-tack sign, Raynaud's, immunological tests, cutaneous lupus, MCTD, Rowell's, lupus anticoagulant);
# facts checked with IADVL 5e and current EULAR/ACR classification criteria.
PYQ = "Previous-year PG question papers (Sahana P Raju, Solved Papers Dermatology)"
IA = "IADVL Textbook of Dermatology 5e"

D = [
dict(case="Dermatomyositis", src=f"{PYQ}; {IA} (Dermatomyositis); 2017 EULAR/ACR idiopathic inflammatory myopathy criteria",
 qa=[
 ("Define dermatomyositis (DM).", ["Idiopathic inflammatory myopathy with characteristic skin lesions and proximal symmetrical muscle weakness; part of the IIM group (with polymyositis, inclusion body myositis, immune-mediated necrotising myopathy, antisynthetase syndrome)", "Bimodal: juvenile (5–15 y) and adult (40–60 y), women 2:1"]),
 ("Classify dermatomyositis (Bohan & Peter / Sontheimer).", ["Classic adult DM, juvenile DM, cancer-associated DM, DM overlapping with other CTD", "Clinically amyopathic DM (CADM): skin signs ≥6 months without weakness — amyopathic (normal muscle tests) and hypomyopathic (subclinical abnormal tests)", "Polymyositis (no skin), inclusion body myositis"]),
 ("Describe the pathognomonic and characteristic skin signs (Gottron's — PYQ).", ["Pathognomonic: Gottron's papules (violaceous flat-topped papules over knuckles — MCP, PIP, DIP joints) and Gottron's sign (violaceous macules/patches over extensor surfaces of joints — elbows, knees, knuckles, malleoli)", "Characteristic: heliotrope rash (violet-purple erythema ± oedema of upper eyelids), periungual telangiectasia with cuticular overgrowth and haemorrhages (ragged cuticles — Samitz sign), poikiloderma of photo-exposed areas — V-sign (anterior neck/chest), shawl sign (back and shoulders), holster sign (lateral thighs)", "Others: scalp erythema with scaling and non-scarring alopecia, mechanic's hands (hyperkeratotic fissured lateral fingers — antisynthetase syndrome), calcinosis cutis (juvenile), flagellate erythema, Raynaud's, ulcers (MDA5), panniculitis, vasculitis, pruritus (more than in lupus — helps differentiate)"]),
 ("Describe the muscle involvement.", ["Proximal symmetrical weakness of shoulder and hip girdles (difficulty combing hair, rising from squatting, climbing stairs), neck flexors, pharyngeal muscles (dysphagia, nasal regurgitation, aspiration), respiratory muscles; myalgia; distal and facial muscles spared"]),
 ("Myositis-specific autoantibodies and their associations.", ["Anti-Mi-2: classic DM, prominent skin, good response, low cancer risk", "Anti-TIF1γ (p155/140): strong association with malignancy in adults; severe skin, 'red on white' lesions, palmar hyperkeratotic papules", "Anti-NXP2: calcinosis in juvenile DM, adult malignancy, oedema", "Anti-MDA5 (CADM-140): clinically amyopathic DM, rapidly progressive interstitial lung disease (high mortality — especially in Asians), palmar papules (inverse Gottron's), skin ulcers, arthritis", "Anti-SAE: skin first then muscle, dysphagia", "Antisynthetase (anti-Jo-1, PL-7, PL-12, EJ, OJ): myositis, ILD, mechanic's hands, arthritis, Raynaud's, fever"]),
 ("How do you investigate DM?", ["Muscle enzymes: CK (most sensitive), aldolase, LDH, AST/ALT; may be normal in CADM", "EMG (myopathic pattern: short polyphasic potentials, fibrillation), MRI of thighs (oedema on STIR — guides biopsy), muscle biopsy (perifascicular atrophy, perivascular inflammation, MxA expression)", "Skin biopsy: interface dermatitis with dermal mucin (similar to lupus); DIF usually negative (unlike lupus)", "ANA, myositis-specific/associated antibody panel", "ILD screen: HRCT chest, PFTs (DLCO); ECG/echo for cardiac; barium swallow/manometry for dysphagia", "Cancer screening in adults (especially first 3 years): CBC, CT chest–abdomen–pelvis, ovarian (CA-125, pelvic USG), breast, colorectal, nasopharyngeal (in Asians), PSA; repeat annually for 3 years"]),
 ("Which malignancies are associated with DM?", ["15–25% of adult DM; ovarian, lung, breast, stomach, colorectal, pancreatic, nasopharyngeal carcinoma (Southeast Asia/China), lymphoma", "Risk factors: age >45–50, male, TIF1γ/NXP2 antibodies, rapid onset, cutaneous necrosis/ulcers, dysphagia, normal CK, poor treatment response"]),
 ("Juvenile DM — differences from adult.", ["More vasculopathy (ulceration, lipodystrophy, GI vasculitis), calcinosis (up to 40%), no malignancy association, better prognosis; treat aggressively early (methotrexate + steroids) to prevent calcinosis"]),
 ("Differentiate DM from SLE skin disease.", ["DM: violaceous, itchy, over knuckles (Gottron's), heliotrope, scalp involvement, shawl/V sign poikiloderma, periungual changes, muscle weakness, raised CK", "SLE: pink-red, less itchy, between knuckles (spares joints), malar rash spares nasolabial folds, photosensitivity, ANA/anti-dsDNA, DIF lupus band positive"]),
 ("Management of DM.", ["Photoprotection (broad-spectrum sunscreen), physiotherapy, speech therapy for dysphagia", "Systemic corticosteroids prednisolone 1 mg/kg/day (or IV methylprednisolone pulse for severe) tapered over months", "Steroid-sparing from the start: methotrexate 15–25 mg/week, azathioprine, mycophenolate (also for ILD)", "Skin: topical steroids/tacrolimus, hydroxychloroquine (watch drug rash — common in DM), methotrexate, dapsone, IVIG (very effective for skin and muscle — approved for DM), JAK inhibitors (tofacitinib — refractory skin and MDA5-ILD)", "Refractory: IVIG, rituximab, cyclophosphamide/tacrolimus (ILD), cyclosporine", "Calcinosis: diltiazem, bisphosphonates, probenecid, sodium thiosulphate (topical/intralesional/IV), surgical excision", "Treat underlying malignancy (DM may remit)"]),
 ("Prognosis.", ["5-year survival ~70–90%; worse with malignancy, ILD (MDA5), dysphagia/aspiration, cardiac involvement, older age, delayed treatment"]),
 ],
 spot=["Gottron's papules over knuckles + heliotrope eyelids — dermatomyositis", "Anti-MDA5 — rapidly progressive ILD; anti-TIF1γ — cancer", "Screen for malignancy in adults"]),

dict(case="Systemic lupus erythematosus", src=f"{PYQ}; {IA} (Lupus erythematosus); 2019 EULAR/ACR SLE classification criteria",
 qa=[
 ("Define SLE.", ["Chronic multisystem autoimmune disease with autoantibodies (especially to nuclear antigens) and immune-complex–mediated tissue injury of skin, joints, kidneys, serosa, blood, CNS; women of child-bearing age (F:M ~9:1)"]),
 ("Pathogenesis.", ["Genetic (HLA-DR2/DR3, complement C1q/C2/C4 deficiency, TREX1, IRF5, STAT4) + environmental triggers (UV, drugs, EBV, oestrogen, smoking) → impaired clearance of apoptotic cells → exposure of nuclear antigens → loss of tolerance → autoantibodies → immune complexes deposit → complement activation and inflammation", "Type I interferon signature (plasmacytoid DCs) — basis for anifrolumab; B-cell hyperactivity (BAFF/BLyS — belimumab)"]),
 ("Discuss the latest classification of SLE (PYQ).", ["2019 EULAR/ACR criteria: entry criterion ANA ≥1:80 on HEp-2 cells (ever); then additive weighted criteria in 7 clinical and 3 immunological domains; classify as SLE with ≥10 points and ≥1 clinical criterion (each counted only highest in a domain)", "Clinical: constitutional (fever 2); haematological (leucopenia 3, thrombocytopenia 4, autoimmune haemolysis 4); neuropsychiatric (delirium 2, psychosis 3, seizure 5); mucocutaneous (non-scarring alopecia 2, oral ulcers 2, subacute cutaneous or discoid lupus 4, acute cutaneous lupus 6); serosal (effusion 5, acute pericarditis 6); musculoskeletal (joint involvement 6); renal (proteinuria >0.5 g/24 h 4, class II/V nephritis 8, class III/IV nephritis 10)", "Immunological: antiphospholipid antibodies 2; complement — low C3 or C4 3, low C3 and C4 4; SLE-specific antibodies — anti-dsDNA or anti-Smith 6", "Earlier: 1997 ACR (4 of 11) and 2012 SLICC (4 of 17 with ≥1 clinical and ≥1 immunological, or biopsy-proven lupus nephritis with ANA/anti-dsDNA)"]),
 ("Describe the cutaneous manifestations of lupus (Gilliam classification — PYQ).", ["LE-specific: acute cutaneous LE (ACLE — malar 'butterfly' rash sparing nasolabial folds, generalised photosensitive eruption, TEN-like ACLE), subacute cutaneous LE (SCLE — annular/papulosquamous, anti-Ro, drug-induced), chronic cutaneous LE (CCLE — DLE, lupus profundus/panniculitis, chilblain lupus, lupus tumidus, hypertrophic/verrucous DLE, mucosal DLE, LP–LE overlap)", "LE-non-specific: vascular — Raynaud's, livedo reticularis, vasculitis (urticarial, leukocytoclastic), periungual telangiectasia, thrombophlebitis, Degos-like lesions; non-scarring alopecia (lupus hair — frontal broken hairs), oral ulcers (painless palatal), bullous SLE, calcinosis, rheumatoid nodules, sclerodactyly, erythema multiforme-like (Rowell's)", "Risk of SLE: ACLE ~100% association, SCLE ~50% meet criteria (mild), DLE ~5–10% (higher if widespread)"]),
 ("Discuss the systemic manifestations (renal and cardiac — PYQ).", ["Constitutional: fever, fatigue, weight loss", "Musculoskeletal: non-erosive polyarthritis (Jaccoud's arthropathy — reducible deformities), avascular necrosis (steroids), myositis", "Renal (lupus nephritis, 40–60%) — ISN/RPS classes: I minimal mesangial, II mesangial proliferative, III focal (<50% glomeruli), IV diffuse (≥50% — most common and severe; 'wire loop' lesions), V membranous, VI advanced sclerosing; monitor urine protein, sediment, creatinine; biopsy if proteinuria >0.5 g/day", "Cardiac: pericarditis (commonest), myocarditis, Libman–Sacks (non-infective verrucous) endocarditis on mitral valve, premature atherosclerosis/CAD; congenital heart block in neonatal lupus (anti-Ro)", "Lungs: pleuritis/effusion, pneumonitis, alveolar haemorrhage, shrinking lung, pulmonary hypertension", "Haematological: anaemia (chronic disease, AIHA), leucopenia/lymphopenia, thrombocytopenia, APS", "Neuropsychiatric: seizures, psychosis, cognitive dysfunction, stroke, neuropathy", "GI: serositis, mesenteric vasculitis, hepatitis; eyes: retinal vasculitis (cytoid bodies), sicca"]),
 ("Describe the various immunological tests (PYQ).", ["ANA by IIF on HEp-2 — most sensitive (>95%) screening; patterns: homogeneous (dsDNA, histone), speckled (Sm, RNP, Ro, La), nucleolar (scleroderma), centromere (limited SSc), rim/peripheral (dsDNA)", "Anti-dsDNA — specific (~95%); titre correlates with nephritis/activity", "Anti-Sm — most specific (~99%), low sensitivity", "Anti-histone — drug-induced lupus (>95%)", "Anti-Ro (SS-A)/La (SS-B) — SCLE, neonatal lupus, Sjögren's, ANA-negative lupus", "Anti-U1 RNP — MCTD", "Antiphospholipid: anticardiolipin, anti-β2 glycoprotein I, lupus anticoagulant", "Complements C3, C4 (low in active disease), CH50; anti-C1q (nephritis); Coombs test; ESR high with normal CRP (unless infection/serositis)"]),
 ("Write a short note on the LE cell phenomenon (PYQ).", ["Neutrophil that has phagocytosed the denatured nuclear material (homogeneous haematoxylin body) of another cell opsonised by antinuclear (anti-histone/DNA) antibodies — described by Hargraves (1948)", "Positive in ~70–80% of SLE but also in drug-induced lupus, RA, hepatitis; now replaced by ANA/anti-dsDNA testing"]),
 ("Write a short note on the lupus band test (PYQ).", ["DIF showing continuous granular band of immunoglobulins (IgG, IgM, ± IgA) and complement (C3) along the dermo-epidermal junction", "Lesional skin: positive in DLE (~70–90%) and SLE lesions", "Non-lesional skin: sun-protected (buttock/inner arm) positive in ~50% SLE (associated with nephritis and active disease); sun-exposed non-lesional positive in ~70–80% SLE", "False positives: rosacea, PMLE, normal sun-exposed skin (usually only IgM)"]),
 ("What is the antiphospholipid syndrome? (lupus anticoagulant — PYQ)", ["Arterial/venous thrombosis and/or pregnancy morbidity (recurrent miscarriage <10 weeks, fetal death >10 weeks, pre-eclampsia/placental insufficiency) with persistently positive antiphospholipid antibodies (12 weeks apart)", "Lupus anticoagulant: paradoxically prolongs phospholipid-dependent clotting tests in vitro (aPTT, dilute Russell viper venom time) not corrected by mixing with normal plasma but corrected by adding excess phospholipid — but causes thrombosis in vivo", "Skin: livedo reticularis/racemosa, ulcers, necrosis, splinter haemorrhages, Degos-like lesions, anetoderma, catastrophic APS", "Treatment: warfarin (INR 2–3) for thrombosis; aspirin + LMWH in pregnancy"]),
 ("How do you assess disease activity?", ["SLEDAI-2K, BILAG, ECLAM; CLASI for skin (activity and damage); SLICC/ACR damage index"]),
 ("Management of SLE.", ["All: photoprotection, hydroxychloroquine 200–400 mg/day (≤5 mg/kg real body weight) for every patient unless contraindicated — reduces flares, damage, thrombosis; annual eye screening after 5 years (baseline)", "Mild (skin, joints): HCQ, NSAIDs, low-dose prednisolone, topical steroids/tacrolimus", "Moderate: prednisolone ≤7.5 mg/day long-term target, methotrexate, azathioprine, mycophenolate", "Severe organ (nephritis class III/IV, CNS): IV methylprednisolone pulses, mycophenolate or low-dose IV cyclophosphamide (Euro-Lupus), belimumab add-on, voclosporin, obinutuzumab", "Biologics: belimumab (anti-BLyS), anifrolumab (type I IFN receptor antibody — also good for skin), rituximab (off-label)", "Manage comorbidities: cardiovascular risk, bone health, infections (vaccines), APS anticoagulation, pregnancy planning (disease quiet ≥6 months; continue HCQ, aspirin)"]),
 ("What is drug-induced lupus?", ["Classic: procainamide, hydralazine, isoniazid, minocycline, quinidine, methyldopa, TNF inhibitors, chlorpromazine; slow acetylators", "Features: arthralgia, serositis, fever; renal/CNS/skin rare; anti-histone antibodies; anti-dsDNA usually negative (except anti-TNF); resolves on withdrawal", "Drug-induced SCLE: terbinafine, hydrochlorothiazide, calcium channel blockers, PPIs, ACE inhibitors, taxanes, griseofulvin, anti-TNF — anti-Ro positive"]),
 ("What is neonatal lupus?", ["Transplacental maternal anti-Ro/La antibodies → annular erythematous lesions (periorbital 'raccoon eyes'), photosensitive, resolves by 6 months; congenital heart block (permanent — needs pacing), hepatobiliary disease, cytopenias", "Mother may be asymptomatic; future pregnancies risk ~15–20%; HCQ during pregnancy reduces heart block risk"]),
 ("Write a note on mixed connective tissue disease (MCTD — PYQ).", ["Overlap of SLE, SSc, polymyositis/DM features with high titre anti-U1 RNP antibodies", "Raynaud's (nearly all), puffy/swollen hands (sausage fingers), sclerodactyly, arthritis, myositis, oesophageal dysmotility, pulmonary hypertension (main cause of death); renal and CNS disease uncommon", "Treatment according to organ involvement; steroids responsive features (myositis, serositis)"]),
 ],
 spot=["Malar rash sparing nasolabial folds — ACLE", "2019 EULAR/ACR: ANA ≥1:80 entry + ≥10 points", "Anti-Sm most specific; anti-dsDNA tracks nephritis; anti-histone — drug lupus"]),

dict(case="Systemic sclerosis (scleroderma)", src=f"{PYQ}; {IA} (Scleroderma); 2013 ACR/EULAR SSc classification criteria",
 qa=[
 ("Classify scleroderma (PYQ).", ["Localised scleroderma (morphoea) — skin ± underlying tissue, no internal organ disease: plaque, generalised, linear (including en coup de sabre and Parry–Romberg), deep, pansclerotic, mixed", "Systemic sclerosis (SSc): limited cutaneous (lcSSc — skin thickening distal to elbows/knees ± face; includes CREST), diffuse cutaneous (dcSSc — proximal limbs and trunk), SSc sine scleroderma (internal disease + antibodies without skin thickening), overlap syndromes", "Scleroderma-like disorders: scleredema, scleromyxoedema, nephrogenic systemic fibrosis, eosinophilic fasciitis, chronic GVHD, porphyria cutanea tarda, phenylketonuria, drug/toxin-induced (bleomycin, taxanes, vinyl chloride, silica, toxic oil, L-tryptophan)"]),
 ("Explain the pathogenesis.", ["Triad: vasculopathy (endothelial injury → intimal proliferation, obliteration, Raynaud's, ischaemia) + immune activation (autoantibodies, T/B cells, IL-6, type I IFN) + fibrosis (TGF-β, PDGF, CTGF → myofibroblasts producing excess collagen in skin and organs)"]),
 ("Describe skin features.", ["Raynaud's phenomenon (first symptom in >90%)", "Oedematous (puffy fingers) → indurated → atrophic phases", "Sclerodactyly (tapered, tight, shiny fingers with flexion contractures), digital pitting scars, ulcers on fingertips and knuckles, resorption of terminal phalanges (acro-osteolysis)", "Face: mask-like expressionless face, beaked nose, microstomia with radial perioral furrowing (purse-string mouth), loss of wrinkles", "Salt-and-pepper pigmentation (perifollicular retention with depigmentation), telangiectasias (matted), calcinosis cutis, nailfold capillary changes, pruritus (early)"]),
 ("Write a short note on Raynaud's phenomenon (PYQ).", ["Episodic vasospasm of digital arteries on exposure to cold/stress — triphasic colour change: white (ischaemia/pallor) → blue (cyanosis) → red (reactive hyperaemia), with pain/numbness", "Primary (Raynaud's disease — young women, symmetrical, no ulcers, normal nailfold capillaries, ANA negative) vs secondary (SSc, SLE, MCTD, DM, Sjögren's, cryoglobulinaemia, vibration tools, thoracic outlet, drugs — β-blockers, ergots)", "Treatment: keep warm, gloves, stop smoking; calcium channel blockers (nifedipine SR, amlodipine) first line; losartan, fluoxetine, topical nitrates, PDE5 inhibitors (sildenafil, tadalafil), IV iloprost, bosentan (prevents new digital ulcers), botulinum toxin, sympathectomy"]),
 ("Write a short note on CREST syndrome (PYQ).", ["Limited cutaneous SSc variant: Calcinosis cutis, Raynaud's phenomenon, oEsophageal dysmotility, Sclerodactyly, Telangiectasia (mat-like on face, hands)", "Anti-centromere antibodies (~50–90%); slower course; late complications — pulmonary arterial hypertension, primary biliary cholangitis"]),
 ("Write a short note on calcinosis cutis (PYQ).", ["Deposition of insoluble calcium salts in skin", "Types: dystrophic (normal calcium/phosphate; damaged tissue — SSc, DM, lupus, tumours, trauma), metastatic (high Ca × P product — CKD, hyperparathyroidism, hypervitaminosis D, milk-alkali), idiopathic (scrotal calcinosis, subepidermal calcified nodule, tumoral calcinosis), iatrogenic (calcium gluconate extravasation, EEG paste), calciphylaxis (vascular calcification in CKD — painful necrosis, high mortality)", "Treatment: treat cause; diltiazem, bisphosphonates, warfarin (low dose), probenecid, colchicine (inflammation), sodium thiosulphate, excision, CO2 laser, lithotripsy"]),
 ("What are the systemic features?", ["GI (90%): oesophageal dysmotility (dysphagia, reflux, Barrett's), watermelon stomach (GAVE), small bowel bacterial overgrowth, pseudo-obstruction, wide-mouthed colonic diverticula, faecal incontinence", "Lungs: interstitial lung disease (leading cause of death — dcSSc, anti-Scl-70), pulmonary arterial hypertension (lcSSc, anti-centromere)", "Kidney: scleroderma renal crisis — sudden hypertension, AKI, microangiopathic haemolysis (dcSSc, anti-RNA polymerase III, high-dose steroids >15 mg/day) — ACE inhibitors are life-saving", "Heart: myocardial fibrosis, arrhythmias, pericarditis", "Musculoskeletal: tendon friction rubs (dcSSc — poor prognosis), arthralgia, myopathy; also sicca, hypothyroidism, erectile dysfunction"]),
 ("Antibodies and their associations.", ["Anti-topoisomerase I (Scl-70): dcSSc, ILD", "Anti-centromere: lcSSc/CREST, PAH, digital loss", "Anti-RNA polymerase III: rapid diffuse skin, renal crisis, cancer association (synchronous)", "Anti-U3 RNP (fibrillarin): PAH, myositis, young men of African descent", "Anti-PM/Scl: overlap with myositis; anti-Th/To: lcSSc with ILD/PAH"]),
 ("Give the 2013 ACR/EULAR classification criteria.", ["Skin thickening of fingers of both hands extending proximal to MCP joints — sufficient alone (9 points)", "Otherwise add: skin thickening of fingers — puffy fingers 2 or sclerodactyly distal to MCP 4 (higher counted); fingertip lesions — digital ulcers 2 or pitting scars 3; telangiectasia 2; abnormal nailfold capillaries 2; PAH and/or ILD 2; Raynaud's 3; SSc-related antibodies (anti-centromere, Scl-70, RNA pol III) 3", "Total ≥9 = definite SSc (excludes scleroderma-like disorders)"]),
 ("Investigations in SSc.", ["ANA (nucleolar/centromere/speckled), specific antibodies; nailfold capillaroscopy (giant capillaries, haemorrhages, avascular areas — 'scleroderma pattern': early, active, late)", "HRCT chest, PFT with DLCO, 6-minute walk, echocardiography ± right-heart catheterisation for PAH, NT-proBNP", "Renal function, BP, urine; upper GI endoscopy/manometry; skin score (modified Rodnan skin score, 17 sites 0–3, max 51)"]),
 ("Management of SSc (organ-based).", ["Skin: methotrexate, mycophenolate (first choice for dcSSc skin + ILD), cyclophosphamide, rituximab, IVIG, autologous haematopoietic stem cell transplant for rapidly progressive dcSSc; physiotherapy", "Raynaud's/digital ulcers: as above (CCB, PDE5i, iloprost, bosentan)", "ILD: mycophenolate, cyclophosphamide, tocilizumab (anti-IL-6R), nintedanib (antifibrotic), rituximab, lung transplant", "PAH: endothelin receptor antagonists (bosentan, ambrisentan, macitentan), PDE5 inhibitors, prostacyclin analogues, riociguat", "Renal crisis: ACE inhibitor (captopril) titrated quickly, dialysis; avoid high-dose steroids", "GI: PPIs, prokinetics, rotating antibiotics for bacterial overgrowth", "Calcinosis and telangiectasia: as above; pulsed-dye laser for telangiectasia"]),
 ("Prognosis.", ["10-year survival ~70%; dcSSc worse; deaths mainly from ILD, PAH, cardiac disease; renal crisis mortality reduced by ACE inhibitors"]),
 ],
 spot=["Sclerodactyly + microstomia + salt-and-pepper pigmentation — SSc", "Anti-Scl-70 → ILD; anti-centromere → CREST/PAH; anti-RNA pol III → renal crisis", "Renal crisis — ACE inhibitor"]),

dict(case="Discoid lupus erythematosus", src=f"{PYQ}; {IA} (Cutaneous lupus erythematosus)",
 qa=[
 ("What is discoid lupus erythematosus (DLE)?", ["Commonest form of chronic cutaneous lupus — scarring, photosensitive plaques with adherent scale, follicular plugging, atrophy and dyspigmentation, mostly on head and neck; women 20–40 y; ~5–10% (more if widespread) develop SLE"]),
 ("Describe the lesion.", ["Well-defined red-violaceous plaques with adherent scale extending into dilated follicles; on lifting, scale shows keratotic spikes on its undersurface — carpet-tack (tin-tack) sign", "Evolution: centre becomes atrophic, scarred, depigmented with hyperpigmented active border (in dark skin), telangiectasia", "Sites: face (malar, nose, ears — concha and external ear canal very typical), scalp (scarring alopecia), lips, V of neck, arms; localised (above the neck) vs generalised (above and below the neck — higher SLE risk)"]),
 ("Name the variants of chronic cutaneous lupus.", ["Hypertrophic/verrucous DLE (extensor arms — mimics SCC/keratoacanthoma), mucosal DLE (lips, oral — risk of SCC), lupus profundus/panniculitis (deep nodules → lipoatrophy; face, upper arms, buttocks), chilblain lupus (acral purple papules in cold), lupus tumidus (urticarial plaques without epidermal change, very photosensitive), LP–LE overlap, childhood DLE"]),
 ("Differentiate DLE from LP (PYQ).", ["See LP case — key points: DLE has adherent scale with follicular plugging, atrophy, scarring, depigmentation, photodistribution, ears and scalp; LP has purple flat papules with Wickham's striae, flexures, no atrophy (except atrophic/LPP), hyperpigmentation; histology and DIF differ (lupus band vs fibrinogen/cytoid bodies)"]),
 ("Differential diagnosis.", ["Face: psoriasis, seborrhoeic dermatitis, rosacea, polymorphic light eruption, sarcoidosis (lupus pernio), lupus vulgaris (apple-jelly, no follicular plugs), tinea faciei, tuberculoid leprosy, actinic keratosis/SCC (hypertrophic), Jessner's lymphocytic infiltrate, lymphocytoma cutis", "Scalp: lichen planopilaris, folliculitis decalvans, morphoea (en coup de sabre), tinea capitis (kerion), pseudopelade of Brocq, alopecia areata"]),
 ("Histopathology of DLE.", ["Hyperkeratosis with follicular plugging, epidermal atrophy, vacuolar interface dermatitis with Civatte bodies, thickened PAS-positive basement membrane, superficial and deep perivascular and periadnexal lymphocytic infiltrate (patchy, dense), dermal mucin, pigment incontinence; scarring alopecia with loss of sebaceous glands", "DIF: granular IgG/IgM/C3 at DEJ (lupus band) in ~70–90% of lesions >6 weeks old"]),
 ("Investigations.", ["Biopsy + DIF; CBC, ESR, urinalysis (proteinuria/haematuria), renal function, ANA, anti-dsDNA, anti-Ro, C3/C4 to screen for SLE; repeat yearly in generalised DLE"]),
 ("Management.", ["Strict photoprotection: broad-spectrum sunscreen SPF ≥30 (UVA+UVB) daily, hats, clothing; stop smoking (reduces HCQ efficacy)", "Topical: potent/super-potent steroids (clobetasol) on body/scalp, mid-potency on face; tacrolimus 0.1% ointment (face); intralesional triamcinolone 2.5–10 mg/ml for thick or scalp lesions", "Systemic first-line: hydroxychloroquine 200–400 mg/day (≤5 mg/kg) — response in 2–3 months; chloroquine (more retinal risk) or add quinacrine (no retinopathy) if poor response", "Second-line: methotrexate, mycophenolate, dapsone (bullous/profundus), acitretin/isotretinoin (hypertrophic), thalidomide/lenalidomide (refractory — neuropathy, teratogenicity), anifrolumab (newer), JAK inhibitors (experimental)", "Camouflage, scar revision when inactive; lip lesions — monitor for SCC"]),
 ("What is antimalarial retinopathy and its screening?", ["Bull's-eye maculopathy from cumulative dose; risk factors: dose >5 mg/kg/day real weight (HCQ), >5 years use, kidney disease, tamoxifen, pre-existing maculopathy", "Baseline eye exam then annual screening after 5 years (earlier if risk factors) — SD-OCT and automated visual fields (10-2)"]),
 ("Complications of DLE.", ["Permanent scarring, scarring alopecia, depigmentation (cosmetic disfigurement), SCC in long-standing scars (lips, ears, scalp), progression to SLE (~5–10%)"]),
 ],
 spot=["Carpet-tack (tin-tack) sign — DLE", "Concha of ear involvement — classic DLE", "Lupus band on lesional DIF"]),
]
